import { ADMIN_ROLES, COLLABORATOR_ROLES } from "../types/plugin-input";
function isAdminRole(role) {
    return ADMIN_ROLES.includes(role.toLowerCase());
}
function isCollaboratorRole(role) {
    return COLLABORATOR_ROLES.includes(role.toLowerCase());
}
export function getTransformedRole(role) {
    role = role.toLowerCase();
    if (isAdminRole(role)) {
        return "admin";
    }
    else if (isCollaboratorRole(role)) {
        return "collaborator";
    }
    return "contributor";
}
function getUserTaskLimit(maxConcurrentTasks, role) {
    if (isAdminRole(role)) {
        return Infinity;
    }
    if (isCollaboratorRole(role)) {
        return maxConcurrentTasks.collaborator;
    }
    return maxConcurrentTasks.contributor;
}
export async function getUserRoleAndTaskLimit(context, user) {
    const orgLogin = context.payload.organization?.login;
    const { config, logger, installOctokit } = context;
    const { maxConcurrentTasks } = config;
    try {
        // Validate the organization login
        if (typeof orgLogin !== "string" || orgLogin.trim() === "") {
            throw context.logger.warn("Invalid organization name");
        }
        let role;
        let limit;
        try {
            const response = await installOctokit.rest.orgs.getMembershipForUser({
                org: orgLogin,
                username: user,
            });
            role = response.data.role.toLowerCase();
            const normalizedRole = getTransformedRole(role);
            limit = getUserTaskLimit(maxConcurrentTasks, normalizedRole);
            return { role: normalizedRole, limit };
        }
        catch (err) {
            logger.error("Could not get user membership", { err });
        }
        // If we failed to get organization membership, narrow down to repo role
        try {
            const permissionLevel = await installOctokit.rest.repos.getCollaboratorPermissionLevel({
                username: user,
                owner: context.payload.repository.owner.login,
                repo: context.payload.repository.name,
            });
            role = permissionLevel.data.role_name?.toLowerCase();
            context.logger.debug(`Retrieved collaborator permission level for ${user}.`, {
                user,
                owner: context.payload.repository.owner.login,
                repo: context.payload.repository.name,
                isAdmin: permissionLevel.data.user?.permissions?.admin,
                role,
                data: permissionLevel.data,
            });
            const normalizedRole = getTransformedRole(role);
            limit = getUserTaskLimit(maxConcurrentTasks, normalizedRole);
            return { role: normalizedRole, limit };
        }
        catch (err) {
            logger.error("Could not get collaborator permission level", { err });
        }
    }
    catch (err) {
        logger.error("Could not get user role", { err });
    }
    return { role: "contributor", limit: maxConcurrentTasks.contributor };
}
