import { QUERY_OPEN_LINKED_PULL_REQUESTS_FOR_ISSUE } from "../github-queries";
export async function getOpenLinkedPullRequestsForIssue(context, { owner, repository, issue }) {
    if (!issue) {
        throw context.logger.error("Issue is not defined");
    }
    const linkedPullRequests = await context.octokit.graphql.paginate(QUERY_OPEN_LINKED_PULL_REQUESTS_FOR_ISSUE, {
        owner,
        repo: repository,
        issue_number: issue,
    });
    const pullRequests = linkedPullRequests.repository?.issue?.closedByPullRequestsReferences?.nodes;
    if (!pullRequests) {
        return [];
    }
    return pullRequests
        .filter((pullRequest) => !!pullRequest)
        .map((pullRequest) => ({
        organization: pullRequest.repository.owner.login,
        repository: pullRequest.repository.name,
        number: pullRequest.number,
        href: pullRequest.url,
        author: pullRequest.author?.login ?? "",
    }));
}
