import { HttpStatusCode } from "../types/result-types";
import { QUERY_CLOSING_ISSUE_REFERENCES } from "../utils/get-closing-issue-references";
import { getUserRoleAndTaskLimit } from "../utils/get-user-task-limit-and-role";
import { closePullRequest, getOwnerRepoFromHtmlUrl } from "../utils/issue";
import { createRepoOctokit } from "./start/api/helpers/octokit";
import { ERROR_MESSAGES } from "./start/helpers/error-messages";
import { startTask } from "./start-task";
function formatMessage(template, username) {
    return template.replace("{{user}}", username);
}
function isClosedIssue(issue) {
    return String(issue.state).toUpperCase() === "CLOSED";
}
function getAssigneeLogins(issue) {
    return issue.assignees.nodes?.flatMap((assignee) => (assignee?.login ? [assignee.login.toLowerCase()] : [])) ?? [];
}
export async function newPullRequestOrEdit(context) {
    const { payload } = context;
    const { pull_request } = payload;
    if (!pull_request.user) {
        context.logger.debug("Pull request has no user associated, skipping.");
        return { status: HttpStatusCode.NOT_MODIFIED };
    }
    async function commentOnTriggeredPullRequest(body) {
        try {
            const warningCommentBody = context.logger.warn(body);
            const commentBody = context.commentHandler.createCommentBody(context, warningCommentBody);
            await context.octokit.rest.issues.createComment({
                owner: payload.repository.owner.login,
                repo: payload.repository.name,
                issue_number: pull_request.number,
                body: commentBody,
            });
        }
        catch (err) {
            context.logger.warn("Failed to comment on triggering pull request.", {
                err,
                pullRequestNumber: pull_request.number,
            });
        }
    }
    async function closeTriggeredPullRequest() {
        try {
            await closePullRequest(context, { number: pull_request.number });
        }
        catch (err) {
            context.logger.warn("Failed to close triggering pull request.", {
                err,
                pullRequestNumber: pull_request.number,
            });
        }
    }
    async function commentAndCloseTriggeredPullRequest(body) {
        await commentOnTriggeredPullRequest(body);
        await closeTriggeredPullRequest();
        return {
            status: HttpStatusCode.BAD_REQUEST,
            content: body,
        };
    }
    const sourceRepoOctokit = await createRepoOctokit(context.env, payload.repository.owner.login, payload.repository.name);
    const { role } = await getUserRoleAndTaskLimit({
        ...context,
        installOctokit: sourceRepoOctokit,
    }, pull_request.user.login);
    const { owner, repo } = getOwnerRepoFromHtmlUrl(pull_request.html_url);
    const linkedIssues = await context.octokit.graphql.paginate(QUERY_CLOSING_ISSUE_REFERENCES, {
        owner,
        repo,
        issue_number: pull_request.number,
    });
    const issues = (linkedIssues.repository.pullRequest?.closingIssuesReferences?.nodes ?? []).filter((issue) => !!issue);
    const openIssues = issues.filter((issue) => !isClosedIssue(issue));
    const openUnassignedIssues = openIssues.filter((issue) => getAssigneeLogins(issue).length === 0);
    const openIssuesAssignedToAuthor = openIssues.filter((issue) => getAssigneeLogins(issue).includes(pull_request.user.login.toLowerCase()));
    const openIssuesAssignedToOtherUsers = openIssues.filter((issue) => {
        const assignees = getAssigneeLogins(issue);
        return assignees.length > 0 && !assignees.includes(pull_request.user.login.toLowerCase());
    });
    async function publishLeaveOpenReceipt(reason) {
        try {
            const appId = Number(context.env.APP_ID);
            const botUserId = Number(context.env.BOT_USER_ID);
            const updatedAt = Date.parse(pull_request.updated_at);
            if (!Number.isSafeInteger(appId) || appId <= 0 || !Number.isSafeInteger(botUserId) || botUserId <= 0 || !Number.isFinite(updatedAt)) {
                throw new Error("Ownership receipt identity or event timestamp is unavailable.");
            }
            const receipt = {
                eventName: context.eventName,
                action: payload.action,
                repository: `${payload.repository.owner.login}/${payload.repository.name}`,
                pullRequest: pull_request.number,
                author: pull_request.user?.login,
                head: { sha: pull_request.head.sha, ref: pull_request.head.ref },
                base: { sha: pull_request.base.sha, ref: pull_request.base.ref },
                updatedAt: pull_request.updated_at,
                role,
                reason,
                result: "leave_open",
            };
            const prefix = "<!-- uos-command-start-stop:ownership-receipt:v1\n";
            const metadata = JSON.stringify(receipt).replace(/[<>&`@]/g, (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`);
            const locator = { owner: payload.repository.owner.login, repo: payload.repository.name };
            const comments = await context.octokit.paginate(context.octokit.rest.issues.listComments, {
                ...locator,
                issue_number: pull_request.number,
                per_page: 100,
            });
            const ownedComments = comments.filter((comment) => comment.user?.type === "Bot" && comment.user.id === botUserId && comment.performed_via_github_app?.id === appId && comment.body?.startsWith(prefix));
            for (const comment of ownedComments) {
                const previousMetadata = comment.body?.slice(prefix.length, comment.body.indexOf("\n-->", prefix.length)) ?? "";
                const previous = JSON.parse(previousMetadata);
                if (typeof previous?.updatedAt !== "string" ||
                    !Number.isFinite(Date.parse(previous.updatedAt)) ||
                    previous.repository !== receipt.repository ||
                    previous.pullRequest !== receipt.pullRequest) {
                    throw new Error("Ownership receipt metadata is unavailable.");
                }
                if (Date.parse(previous.updatedAt) > updatedAt || previousMetadata === metadata)
                    return;
            }
            const message = context.logger.debug("Ownership check: this pull request is left open.");
            const body = `${prefix}${metadata}\n-->\n${context.commentHandler.createCommentBody(context, message)}`;
            const previousComment = ownedComments[0];
            if (previousComment) {
                await context.octokit.rest.issues.updateComment({ ...locator, comment_id: previousComment.id, body });
            }
            else {
                // The API has no atomic create-if-absent operation; concurrent first invocations can both publish.
                await context.octokit.rest.issues.createComment({ ...locator, issue_number: pull_request.number, body });
            }
        }
        catch {
            context.logger.warn("Failed to publish pull request ownership receipt.");
        }
    }
    const eligibleIssue = openUnassignedIssues[0];
    if (!eligibleIssue) {
        if (openIssuesAssignedToAuthor.length > 0) {
            context.logger.debug("Pull request is linked to an open issue already assigned to the author, leaving it open.", {
                pullRequestNumber: pull_request.number,
            });
            await publishLeaveOpenReceipt("author_assigned");
            return { status: HttpStatusCode.NOT_MODIFIED };
        }
        if (role !== "contributor") {
            context.logger.debug("Non-contributor pull request has no eligible linked issue, leaving it open.", {
                pullRequestNumber: pull_request.number,
                role,
            });
            await publishLeaveOpenReceipt("non_contributor_no_eligible_issue");
            return { status: HttpStatusCode.NOT_MODIFIED };
        }
        if (openIssuesAssignedToOtherUsers.length > 0) {
            return commentAndCloseTriggeredPullRequest(formatMessage(ERROR_MESSAGES.PULL_REQUEST_LINKED_TO_OTHER_ASSIGNEE, pull_request.user.login));
        }
        return commentAndCloseTriggeredPullRequest(formatMessage(ERROR_MESSAGES.INVALID_PULL_REQUEST_LINK, pull_request.user.login));
    }
    const repoOctokit = await createRepoOctokit(context.env, eligibleIssue.repository.owner.login, eligibleIssue.repository.name);
    const linkedIssue = (await repoOctokit.rest.issues.get({
        owner: eligibleIssue.repository.owner.login,
        repo: eligibleIssue.repository.name,
        issue_number: eligibleIssue.number,
    })).data;
    const repository = (await repoOctokit.rest.repos.get({
        owner: eligibleIssue.repository.owner.login,
        repo: eligibleIssue.repository.name,
    })).data;
    let organization = undefined;
    if (repository.owner.type === "Organization") {
        organization = (await repoOctokit.rest.orgs.get({
            org: eligibleIssue.repository.owner.login,
        })).data;
    }
    const newContext = {
        ...context,
        eventName: "issue_comment.created",
        octokit: repoOctokit,
        payload: {
            ...context.payload,
            issue: linkedIssue,
            repository,
            organization,
            sender: pull_request.user,
        },
    };
    try {
        const result = await startTask(newContext);
        if (result.status !== HttpStatusCode.OK) {
            await closeTriggeredPullRequest();
        }
        return result;
    }
    catch (error) {
        await closeTriggeredPullRequest();
        throw error;
    }
}
