import { createClient } from "@supabase/supabase-js";
import { CommentHandler } from "@ubiquity-os/plugin-sdk";
import { Logs } from "@ubiquity-os/ubiquity-os-logger";
import { createAdapters } from "../../../../adapters/index";
import { AssignedIssueScope, Role } from "../../../../types/plugin-input";
import { MAX_CONCURRENT_DEFAULTS } from "../../../../utils/constants";
import { listOrganizations } from "../../../../utils/list-organizations";
import { createUserOctokit } from "./octokit";
/**
 * Builds a partner context-free context object
 *
 * DOES NOT load payload, repository, issue, organization.
 * These must be injected once you know them.
 */
export async function buildShallowContextObject({ env, accessToken, userId, logger, }) {
    const { octokit, supabase } = await initializeClients(env, accessToken);
    const userData = typeof userId === "number" ? await octokit.rest.users.getById({ account_id: userId }) : await octokit.rest.users.getByUsername({ username: userId });
    const ctx = {
        env,
        octokit,
        logger,
        authToken: accessToken,
        config: getDefaultConfig(),
        command: createCommand([userData.data.login]),
        eventName: "issue_comment.created",
        commentHandler: new CommentHandler(),
        payload: {
            sender: {
                login: userData.data.login,
                id: userData.data.id,
            },
        },
        adapters: {},
        organizations: [],
    };
    ctx.organizations = await listOrganizations(ctx);
    ctx.adapters = createAdapters(supabase, ctx);
    return ctx;
}
export function createPayload({ issue, repository, organization, sender, }) {
    return {
        action: "created",
        issue,
        repository,
        organization,
        sender,
        comment: {
            issue_url: issue.url,
            user: sender,
            body: "/start",
        },
    };
}
export function createCommand(assignees) {
    return {
        name: "start",
        parameters: {
            teammates: assignees,
        },
    };
}
export function getDefaultConfig() {
    return {
        reviewDelayTolerance: "3 Days",
        taskStaleTimeoutDuration: "30 Days",
        maxConcurrentTasks: MAX_CONCURRENT_DEFAULTS,
        startRequiresWallet: false,
        assignedIssueScope: AssignedIssueScope.NETWORK,
        emptyWalletText: "Please set your wallet address with the /wallet command first and try again.",
        rolesWithReviewAuthority: [Role.ADMIN, Role.OWNER, Role.MEMBER],
        requiredLabelsToStart: [
            {
                name: "Priority: 1 (Normal)",
                allowedRoles: ["collaborator", "contributor"],
            },
            {
                name: "Priority: 2 (Medium)",
                allowedRoles: ["collaborator", "contributor"],
            },
            {
                name: "Priority: 3 (High)",
                allowedRoles: ["collaborator"],
            },
            {
                name: "Priority: 4 (Urgent)",
                allowedRoles: ["collaborator"],
            },
            {
                name: "Priority: 5 (Emergency)",
                allowedRoles: ["collaborator"],
            },
        ],
        taskAccessControl: {
            usdPriceMax: {
                collaborator: 5000,
                contributor: -1,
            },
        },
    };
}
export function createLogger(env) {
    return new Logs(env.LOG_LEVEL ?? "info");
}
async function initializeClients(env, accessToken) {
    const octokit = await createUserOctokit(accessToken);
    const supabase = createClient(env.SUPABASE_URL, env.SUPABASE_KEY);
    return { octokit, supabase };
}
